const data = msg.payload;
if (!data || data.valid !== true || data.unit !== "mm" ||
    typeof data.distance_mm !== "number" || !Number.isFinite(data.distance_mm) ||
    data.distance_mm < 0 || data.distance_mm > 1200) {
    node.warn("Expected valid JSON with numeric distance_mm from 0 to 1200 and unit mm");
    return null;
}
if (flow.get("auto") !== true) return null;
let state = flow.get("fan_state") || context.get("fan") || "OFF";
if (data.distance_mm <= 10) state = "OFF";
else if (data.distance_mm >= 30) state = "ON";
context.set("fan", state);
msg.topic = "lab/room1/fan/set";
msg.payload = state;
return msg;
